export const manifest = {
  name: 'Field Notes', short_name: 'Notes', start_url: '/', scope: '/',
  display: 'standalone', lang: 'ko',
  icons: [
    { src: '/icon-192.png', sizes: '192x192', type: 'image/png' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png' }
  ]
};
// 실제 아이콘 파일과 manifest 링크를 배포하고 브라우저별 설치 조건을 확인합니다.

export function mayCache(request: Request, origin: string) {
  const url = new URL(request.url);
  return request.method === 'GET' && url.origin === origin
    && (url.pathname.startsWith('/assets/') || url.pathname === '/offline.html');
}
// 캐시 허용 목록 예시입니다. 인증 API와 비공개 응답은 포함하지 않습니다.

type QueuedChange = { id: string; ownerId: string; baseVersion: number };
export function readyToSync(change: QueuedChange, ownerId: string, serverVersion: number) {
  if (change.ownerId !== ownerId) return 'wrong-account';
  if (change.baseVersion !== serverVersion) return 'conflict';
  return 'ready';
}
// 전송 후 응답을 확인하기 전에는 로컬 큐에서 제거하지 않습니다.

export async function openCamera() {
  const stream = await navigator.mediaDevices.getUserMedia({
    video: { facingMode: { ideal: 'environment' } }, audio: false
  });
  return { stream, stop: () => stream.getTracks().forEach(track => track.stop()) };
}
// 사용자 행동 뒤 호출하고 화면 종료·중단 시 stop을 실행합니다.

type Transcript = { text: string; final: boolean };
export function finalizedText(results: Transcript[]) {
  return results.filter(item => item.final)
    .map(item => item.text.trim()).filter(Boolean).join(' ');
}
// 최종 인식도 사용자가 확인·수정한 뒤 제출하고 원음을 기본 보관하지 않습니다.

export async function cameraPermission() {
  if (!navigator.permissions) return 'unknown';
  try {
    const status = await navigator.permissions.query({ name: 'camera' as PermissionName });
    return status.state;
  } catch { return 'unknown'; }
}
// unknown은 허용이 아닙니다. 카메라 사용 요청 시 실제 API 결과로 처리합니다.
